\frac{
e^{-\alpha_{\mathrm W}x_{m_n}^{(\mathrm{PA})}}
}{
r_{k,m_n}^{\zeta+2}
}
}_{\text{power accumulation}}
+\!
\underbrace{
\begin{aligned}
&\frac{\lambda^2(\zeta+1)D_z^\zeta}{4\pi^2N}
\operatorname{Re}\!\Bigg\{\!
\sum_{1\le n<n'\le N}
\sum_{m=1}^{M}\sum_{m'=1}^{M}
\frac{
e^{-\frac{\alpha_{\mathrm W}}{2}
\left(
x_{m_n}^{(\mathrm{PA})}
+
x_{m'_{n'}}^{(\mathrm{PA})}
\right)}
}{
\left(
r_{k,m_n}r_{k,m'_{n'}}
\right)^{\frac{\zeta+2}{2}}
}
[-1mm]
&\hspace{7mm}\times
e^{-j\left[
k_0
\left(
r_{k,m_n}-r_{k,m'_{n'}}
\right)
+
