\left(
x_{m_n}^{(\mathrm{PA})}
-
x_{m'_{n'}}^{(\mathrm{PA})}
\right)
\right]}
\left[
e^{-j\bm C(L_n-L_{n'})}
\right]_{m,m'}
\!\Bigg\}
\end{aligned}
}_{\text{coherent combining}} .
