\subsection{Rate Upper Bound}
\label{subsec:rate_upper_bound}
Combining the coherence bound in
Proposition~\ref{prop:inter_section_coherence}
with the propagation attenuation and deployment
geometry yields the following channel-gain bound.
\begin{thm}[Coupling-Aware Channel-Gain Upper Bound]
\label{thm:coupling_aware_channel_bound}
Under the local scale-separation and equal-quota
extraction model in
\eqref{eq:waveguide_pa_section_approx},
the effective channel gain satisfies
\begin{align}
&\|\bm h_k\|^2
\le
\frac{
\lambda^2(\zeta+1)e^{-\alpha_{\mathrm W}\underline{x}_1}
}{
8\pi^2D_z^2
}
\left[
1+\frac{2}{N}
\sum_{1\le n<n'\le N}
\cos\theta_{k,nn'}
\right]
\nonumber
&\times
\sum_{m=1}^{M}
\left[
1+
\frac{
\left(
y_m^{(\mathrm{WG})}
-y_k^{(\mathrm{AE})}
\right)^2
}{D_z^2}
\right]^{-\frac{\zeta+2}{2}}.
\label{eq:effective_channel_geometry_bound}
\end{align}
For $N=1$, \eqref{eq:effective_channel_geometry_bound}
reduces to the single-section bound.
\end{thm}
\begin{proof}
From \eqref{eq:waveguide_pa_section_approx},
the channel gain of each extraction section
satisfies
\begin{align}
&\|\bm h_{k,n}\|^2
=
\frac{\lambda^2(\zeta+1)D_z^\zeta}{8\pi^2N}
\sum_{m=1}^{M}
\frac{
e^{-\alpha_{\mathrm W}x_{m_n}^{(\mathrm{PA})}}
}{
r_{k,m_n}^{\zeta+2}
}

\le{}&
\frac{
\lambda^2(\zeta+1)e^{-\alpha_{\mathrm W}\underline{x}_1}
}{
8\pi^2ND_z^2
}
\sum_{m=1}^{M}
\left[
1+
\frac{
(y_m^{(\mathrm{WG})}-y_k^{(\mathrm{AE})})^2
}{D_z^2}
\right]^{-\frac{\zeta+2}{2}},\nonumber
\end{align}
where the inequality follows from
$r_{k,m_n}^2\ge D_z^2+
(y_m^{(\mathrm{WG})}-y_k^{(\mathrm{AE})})^2$
and
$x_{m_n}^{(\mathrm{PA})}\ge
\underline{x}_n\ge\underline{x}_1$.
Combining this uniform section-norm bound
with \eqref{eq:h_k_norm} and
\eqref{eq:inter_section_correlation_bound},
and noting that $\cos\theta_{k,nn'}\ge0$,
directly yields
\eqref{eq:effective_channel_geometry_bound}.
\end{proof}
Combining Theorem~\ref{thm:coupling_aware_channel_bound}
with the transmit-power normalization in \eqref{e:s},
the achievable rate is upper-bounded by
\begin{align}
\label{eq:rate_geometry_upper_bound}
R_k
\!\le\!
\log_2\!\Bigg[
\!1+&
\frac{
P\lambda^2(\zeta\!+\!1)e^{-\alpha_{\mathrm W}\underline{x}_1}
}{
8\pi^2\sigma^2D_z^2
}
\!\Big(
\!1\!+\!\frac{2}{N}\!\!
\sum_{1\le n<n'\le N}
\!\!\!\!\!\cos\theta_{k,nn'}
\!\!\Big)
\nonumber
&\times
\sum_{m=1}^{M}
\Big(
1+
\frac{
(y_m^{(\mathrm{WG})}-y_k^{(\mathrm{AE})})^2
}{D_z^2}
\Big)^{-\frac{\zeta+2}{2}}
\Bigg].
\end{align}
The inter-section coherence factor
$1+\frac{2}{N}\sum_{n<n'}\cos\theta_{k,nn'}$
lies in $[1,N]$. 
Its upper limit recovers the fully coherent-combining ceiling.
Together with guided-wave attenuation and transverse deployment geometry, this factor determines
the rate ceiling. We next investigate its scaling with the number of waveguides under single-agent transmission.
\begin{lem}[Multi-Waveguide Single-Agent Rate-Ceiling Scaling]
\label{lem:rate_bound_scaling}
Consider $M$ equally spaced waveguides with adjacent
spacing $d$, jointly serving a single physical agent
at an arbitrary transverse position $y^{(\mathrm{AE})}$,
measured from the array center.
Under the continuum approximation,
the rate ceiling in \eqref{eq:rate_geometry_upper_bound}
is approximated by
\begin{align}
\label{eq:rate_bound_scaling_M}
&\overline R(M)
\approx\log_2\Bigg[1+
\frac{
P\lambda^2e^{-\alpha_{\mathrm W}\underline{x}_1}
}{
2\pi^2\sigma^2D_zd
}
\mathcal A(\{\theta_{nn'}\})

&\times\Bigg(
\mathcal F\left(
\frac{Md/2-y^{(\mathrm{AE})}}{D_z}
\right)
+
\mathcal F\left(
\frac{Md/2+y^{(\mathrm{AE})}}{D_z}
\right)
\Bigg)\Bigg],\nonumber
\end{align}
where
$\mathcal F(u)\triangleq
\frac{u(3+2u^2)}{[3(1+u^2)^{3/2}]}$.For the small- and large-aperture regimes,
the corresponding asymptotic expressions are
\begin{equation}
\label{eq:rate_bound_asymptotic}
\raisebox{-0.5\height}{
\resizebox{0.88\columnwidth}{!}{$
\displaystyle
\overline R(M)\approx
\begin{cases}
\displaystyle
\log_2\Bigg[
1+
\frac{
P\lambda^2e^{-\alpha_{\mathrm W}\underline{x}_1}
\mathcal A(\{\theta_{nn'}\})M
}{
2\pi^2\sigma^2D_z^2
\left[1+\left(
\frac{y^{(\mathrm{AE})}}{D_z}
\right)^2\right]^{\frac{5}{2}}
}
\Bigg],
& Md\ll D_z,
[4mm]
\displaystyle
\log_2\Bigg[
1+
\frac{
2P\lambda^2e^{-\alpha_{\mathrm W}\underline{x}_1}
\mathcal A(\{\theta_{nn'}\})
}{
3\pi^2\sigma^2D_zd
}
\Bigg],
&
\frac{Md}{2}-|y^{(\mathrm{AE})}|\gg D_z.
\end{cases}
$}}
\end{equation}
where
$\mathcal A(\{\theta_{nn'}\})\triangleq
1+\frac{2}{N}\sum_{n<n'}\cos\theta_{nn'}$
denotes the inter-section coherence factor,
with $\theta_{nn'}$ being the corresponding
inter-section angular bound.
\end{lem}
\begin{proof}
Please see the supplementary material.
\end{proof}
Lemma~\ref{lem:rate_bound_scaling} shows that the transverse
geometric contribution grows approximately linearly with
$M$ for a small aperture, with a reduced gain as the agent
moves away from the array center, and approaches a finite
limit for a sufficiently large aperture.
The overall rate ceiling also depends on guided-wave
attenuation and inter-section coherence.
We next use the general multi-agent rate bound \cite{shao2024theory} to establish
a necessary condition on the number of waveguides for
satisfying prescribed minimum-rate requirements.
\begin{cor}[Necessary Waveguide Count]
\label{cor:waveguide_number_range}
For $M$ equally spaced waveguides with adjacent
spacing $d\ge a$, satisfying $R_k\ge R_0$ for all
$K$ physical agents requires
\begin{align}
\label{eq:waveguide_number_range}
&\Bigg\lceil
\frac{
8\pi^2\sigma^2D_z^2(2^{R_0}-1)
e^{\alpha_{\mathrm W}\underline{x}_1}
}{
P\lambda^2(\zeta+1)
}
\sum_{k=1}^{K}
\left(
\!1\!+\!\frac{2}{N}
\sum_{n<n'}\cos\theta_{k,nn'}
\!\right)^{-1}
\Bigg\rceil
\nonumber
&\qquad\le M
\le 1+\left\lfloor\frac{D_y}{d}\right\rfloor .
\end{align}
\end{cor}
\begin{proof}
Please see the supplementary material.
\end{proof}
Corollary~\ref{cor:waveguide_number_range}
establishes a necessary waveguide-count range
governed by the rate target, guided-wave attenuation,
and inter-section coherence, with the upper limit
set by the available transverse space.
Since $\theta_{k,nn'}$ depends on waveguide and
PA placement, the lower bound provides a
deployment-dependent feasibility condition
rather than an explicit minimum waveguide count.

\section{Sum-Rate Maximization}\label{sec:V}
\label{subsec:joint_optimization}

We formulate a sum-rate maximization problem with
minimum-rate guarantees by jointly optimizing the
waveguide positions $\{y_m^{(\mathrm{WG})}\}$,
PA positions $\{x_{m_n}^{(\mathrm{PA})}\}$,
and digital precoder $\bm W$.
For the considered physical-agent locations and the transverse
deployment interval, the problem is formulated as
\begin{subequations}\label{prob:sumrate}
\begin{align}
\text{(P1):}\quad
&\max_{\substack{
\{x_{m_n}^{(\mathrm{PA})}\},\,
\{y_m^{(\mathrm{WG})}\},\,\bm W
}}
\quad
R_{\mathrm{sum}}
=
\sum_{k=1}^{K}R_k,
\label{e:P1a}

\text{s.t.}\quad
&\operatorname{tr}\!\left(\bm W\bm W^{\mathsf H}\right)\le1,
\label{e:P1b}

&0<x_{m_n}^{(\mathrm{PA})}\le D_x,
\label{e:P1c}

&x_{m_{n+1}}^{(\mathrm{PA})}
-x_{m_n}^{(\mathrm{PA})}
\ge\frac{\lambda}{2},
\quad n<N,
\label{e:P1d}

&0\le y_m^{(\mathrm{WG})}\le D_y,
\label{e:P1e}

&d_{mm'}^{(\mathrm{WG})}\ge a,
\quad m\ne m',
\label{e:P1f}

&\left\|
\bm\psi_k^{(\mathrm{AE})}
-\bm\psi_{k'}^{(\mathrm{AE})}
\right\|
\ge d_{kk'}^{(\mathrm{AE})},
\quad k\ne k',
\label{e:P1g}

&R_k\ge R_0,
\quad k=1,\ldots,K.
\label{e:P1h}
\end{align}
\end{subequations}
Here, $R_0$ is the minimum rate required by each physical agent,
and $R_k$ is the achievable rate defined in \eqref{eq:k_rate}.
Constraint \eqref{e:P1b} normalizes the transmit power, while
\eqref{e:P1c}--\eqref{e:P1d} constrain the PA positions and spacing,
and \eqref{e:P1e}--\eqref{e:P1f} constrain the waveguide deployment
and prevent core overlap.
Constraint \eqref{e:P1g} specifies the minimum separation
between physical agents, while \eqref{e:P1h} imposes the
minimum-rate requirement.
Problem (P1) is nonconvex due to multi-agent interference and the
nonlinear dependence of the effective channel on the waveguide
and PA positions.
In the following sections, we develop a WMMSE-SCA-based
alternating optimization algorithm and a signal-domain PDD
algorithm to solve (P1), both using the full end-to-end
channel in \eqref{eq:end_to_end}.
\subsection{WMMSE-Based Alternating Optimization}
\label{subsubsec:wmmse_ao}
We first transform the sum-rate maximization problem into a weighted
minimum mean-square error (WMMSE) problem. Let $u_k\in\mathbb C$
denote the scalar receiver used by physical agent $k$ to estimate
$s_{0,k}$ from $\xi_k$. According to \eqref{eq:user_received}, the
corresponding mean-square error (MSE) is \cite{shi2011wmmse}
\begin{equation}
e_k
\!=\!
\left|
1-u_k^*\sqrt{P}\bm h_k^{\mathsf H}\bm w_k
\right|^2
\!\!+\!
P\sum_{i\ne k}
\left|
u_k^*\bm h_k^{\mathsf H}\bm w_i
\right|^2
\!+\!\sigma^2|u_k|^2 .
\label{eq:wmmse_mse}
\end{equation}
Introducing $u_k\in\mathbb C$ and $v_k>0$, the achievable
rate admits the WMMSE representation
$R_k=\max_{u_k,v_k}\frac{1+\ln v_k-v_ke_k}{\ln 2}.$
Thus, (P1) is equivalently reformulated as
\begin{subequations}
\label{prob:wmmse}
\begin{align}
\min_{\substack{
\{x_{m_n}^{(\mathrm{PA})}\},
\{y_m^{(\mathrm{WG})}\},
\bm W,\{u_k,v_k\}
}}
\quad&
\sum_{k=1}^{K}
\left(v_ke_k-\ln v_k\right)
\label{eq:wmmse_obj}

\mathrm{s.t.}\quad&
\eqref{e:P1b}-\eqref{e:P1f},
\label{eq:wmmse_geometry_constraints}

& \hspace{-4cm}
v_ke_k-\ln v_k
\le
1-R_0\ln2,
\quad k=1,\ldots,K .
\label{eq:wmmse_qos}
\end{align}
\end{subequations}
Here, \eqref{eq:wmmse_qos} is the WMMSE form of the minimum-rate
constraint in \eqref{e:P1h}. The physical-agent separation constraint
\eqref{e:P1g} does not participate in the optimization since the
physical-agent locations are fixed.
We solve \eqref{prob:wmmse} by alternating optimization over
$\{u_k\}$, $\{v_k\}$, $\bm W$, the PA positions
$\{x_{m_n}^{(\mathrm{PA})}\}$, and the waveguide positions
$\{y_m^{(\mathrm{WG})}\}$. For fixed $\bm W$ and spatial deployment,
the receiver and weight updates admit the closed-form solutions
\begin{equation} 
\label{eq:wmmse_uv_update}
u_k^\star
=
\frac{
\sqrt{P}\bm h_k^{\mathsf H}\bm w_k
}{
P\sum_{i=1}^{K}
|\bm h_k^{\mathsf H}\bm w_i|^2+\sigma^2
},\quad
v_k^\star
=
\left(e_k^\star\right)^{-1}.
\end{equation}
With $\{u_k,v_k\}$ and the spatial deployment fixed, the precoder
is obtained from
\begin{subequations}
\label{prob:wmmse_precoder}
\begin{align}
\min_{\bm W}\quad&
\sum_{k=1}^{K}v_ke_k

\mathrm{s.t.}\quad&
\operatorname{tr}(\bm W\bm W^{\mathsf H})\le1,

&
v_ke_k-\ln v_k
\le1-R_0\ln2,
\quad \forall k .
\end{align}
\end{subequations}
Since $e_k$ is a convex quadratic function of $\bm W$ for fixed
channel and WMMSE variables, \eqref{prob:wmmse_precoder} is a
convex quadratically constrained quadratic program.
We next optimize the spatial deployment. Let $\bm x$ collect all
PA longitudinal positions and let $\bm y$ collect all waveguide
transverse positions. For fixed $\bm W$, $\{u_k,v_k\}$, and the
other geometry block, the MSE remains nonconvex with respect to
either $\bm x$ or $\bm y$ because the spatial variables enter the
coupled waveguide propagation and the PA-to-agent channel.
Accordingly, successive convex approximation (SCA) is applied.
For either geometry block
$\bm z\in\{\bm x,\bm y\}$, at the current point $\bm z^{(t)}$,
we construct
\begin{equation}
\widehat e_k(\bm z)
\!=\!
e_k(\bm z^{(t)})
\!+\!
\nabla_{\bm z}e_k(\bm z^{(t)})^{\top}
\!(\bm z\!-\!\bm z^{(t)})
\!+\!
\frac{\rho_z}{2}
\|\bm z\!-\!\bm z^{(t)}\|_2^2 ,
\label{eq:wmmse_sca}
\end{equation}
where $\rho_z>0$ is selected to make
$\widehat e_k(\bm z)$ a local convex upper approximation of
$e_k(\bm z)$.
The PA-position block is then updated by minimizing
$\sum_kv_k\widehat e_k(\bm x)$ subject to
\eqref{e:P1c}-\eqref{e:P1d} and
$v_k\widehat e_k(\bm x)-\ln v_k\le1-R_0\ln2$.
Similarly, the waveguide-position block minimizes
$\sum_kv_k\widehat e_k(\bm y)$ subject to
\eqref{e:P1e}-\eqref{e:P1f} and the corresponding WMMSE rate
constraints. 
The algorithm therefore updates
$\{u_k\}$, $\{v_k\}$, $\bm W$,
$\{x_{m_n}^{(\mathrm{PA})}\}$, and
$\{y_m^{(\mathrm{WG})}\}$ sequentially in each iteration.
The full channel in \eqref{eq:end_to_end} is recomputed after each
spatial update, and the procedure terminates when the improvement
in the sum rate falls below a prescribed threshold.
