\begin{proof}[Proof of Proposition~\ref{prop:modal_normalization}]
For the isolated guided mode, Maxwell's equation gives
$\bm{\mathcal H}_m^{(\mathrm{iso})}
=-(j\omega\psi_0)^{-1}
\nabla\times\bm{\mathcal E}_m^{(\mathrm{iso})}$.
Under the dominant-field approximation, the
longitudinal magnetic-field component satisfies
$[\bm{\mathcal H}_m^{(\mathrm{iso})}]_z
\!\approx \!\frac{\beta_g[\bm{\mathcal E}_m^{(\mathrm{iso})}]_y}{(\omega\psi_0)}$.
Consequently, the time-averaged Poynting flux
gives the unit-power condition
\begin{align}
1
=&\frac12\operatorname{Re}
\int_{-\infty}^{\infty}
\int_{-\infty}^{\infty}
\Big(
\bm{\mathcal E}_m^{(\mathrm{iso})}
\times
\bm{\mathcal H}_m^{(\mathrm{iso})*}
\Big)\cdot\bm e_x
\,dy\,dz
\nonumber
\approx&
\frac{\beta_g}{2\omega\psi_0}
\int_{-\infty}^{\infty}
\int_{-\infty}^{\infty}
\left\|
\bm{\mathcal E}_m^{(\mathrm{iso})}(x,y,z)
\right\|^2
dy\,dz.
\label{eq:unit_power_condition}
\end{align}
Under the separable Marcatili modal envelope,
the transverse field integral factorizes into
the lateral and vertical contributions.
From \eqref{eq:core_mode_field}, the field
inside the core follows a cosine profile,
while the exterior fields decay exponentially.
The lateral integral, including both cladding
tails, is evaluated as
\begin{align}
&\int_{-a/2}^{a/2}
\cos^2(k_yy)\,dy
+
2\cos^2\left(\frac{k_ya}{2}\right)
\int_0^\infty e^{-2\alpha_y y}\,dy
\nonumber
=&\frac{a}{2}
+\frac{\sin(k_ya)}{2k_y}
+\frac{\cos^2\left(\frac{k_ya}{2}\right)}
{\alpha_y}.
\end{align}
Similarly, the vertical cladding field decays
with the transverse decay constant
$\sqrt{(\omega/c)^2(n_1^2-n_0^2)-k_z^2}$,
as determined by the modal dispersion relations.
The corresponding vertical integral is
\begin{align}
&\int_{-b/2}^{b/2}
\cos^2(k_zz)\,dz+
2\cos^2\left(\frac{k_zb}{2}\right)
\nonumber
&\times
\int_0^\infty
\exp\left[
-2z\sqrt{
\left(\frac{\omega}{c}\right)^2
(n_1^2-n_0^2)-k_z^2
}
\right]dz
\nonumber
=&\frac{b}{2}
+\frac{\sin(k_zb)}{2k_z}
+
\frac{
\cos^2\left(\frac{k_zb}{2}\right)
}{
\sqrt{
\left(\frac{\omega}{c}\right)^2
(n_1^2-n_0^2)-k_z^2
}
}.
\end{align}
Combining the two transverse integrals,
the unit-power condition becomes
\begin{align}
1=&
\frac{\beta_g|\mathcal E_0|^2}
{2\omega\psi_0}
\left[
\frac{a}{2}
+\frac{\sin(k_ya)}{2k_y}
+\frac{\cos^2\left(\frac{k_ya}{2}\right)}
{\alpha_y}
\right]
\nonumber
&\times
\Bigg[
\frac{b}{2}
+\frac{\sin(k_zb)}{2k_z}
+
\frac{
\cos^2\left(\frac{k_zb}{2}\right)
}{
\sqrt{
\left(\frac{\omega}{c}\right)^2
(n_1^2-n_0^2)-k_z^2
}
}
\Bigg].
\end{align}
Solving for the positive normalization factor
$\mathcal E_0$ yields
\eqref{eq:modal_normalization_factor}.
\end{proof}
\begin{proof}[Proof of Theorem~\ref{thm:pairwise_evanescent_field}]
In the homogeneous cladding, the vector wave
equation \eqref{eq:vector_wave_equation} reduces
to the vector Helmholtz equation
\begin{equation*}
\nabla^2\bm{\mathcal E}_m^{(\mathrm{ev})}
+k_0^2n_0^2\bm{\mathcal E}_m^{(\mathrm{ev})}
=\bm 0.
\end{equation*}
Under the Marcatili approximation, the evanescent
field inherits the longitudinal dependence
$e^{-j\beta_gx}$ and vertical dependence
$\cos[k_z(z-D_z)]$ of the fundamental guided mode.
Neglecting the weak longitudinal attenuation
in the transverse modal equation yields
\begin{equation}
\frac{\partial^2\bm{\mathcal E}_m^{(\mathrm{ev})}}
{\partial y^2}
-\alpha_y^2\bm{\mathcal E}_m^{(\mathrm{ev})}
=\bm 0,
\end{equation}
where $\alpha_y^2=\beta_g^2+k_z^2-k_0^2n_0^2$.
Since the evanescent field must remain bounded
away from the waveguide, only the decaying
solution is retained. For
$y>y_m^{(\mathrm{WG})}+a/2$, we obtain
\begin{align}
\bm{\mathcal E}_m^{(\mathrm{ev})}(x,y,z)
=&\bm{\mathcal E}_m^{(\mathrm{WG})}
\left(x,y_m^{(\mathrm{WG})}+\frac a2,z\right)
\nonumber
&\times
\exp\left[
-\alpha_y\left(
y-y_m^{(\mathrm{WG})}-\frac a2
\right)\right].
\label{eq:evanescent_from_boundary}
\end{align}
From \eqref{eq:core_mode_field} and
\eqref{eq:guided_field_CWPASS}, the field
at the right core boundary is
\begin{align*}
\bm{\mathcal E}_m^{(\mathrm{WG})}
\left(x,y_m^{(\mathrm{WG})}+\frac a2,z\right)
\approx&
\mathcal E_0s_m
e^{-\frac{\alpha_{\mathrm W}}2x}
e^{-j\beta_gx}
\cos\left(\frac{k_ya}{2}\right)
\nonumber
&\times\cos[k_z(z-D_z)]\bm e_y.
\end{align*}
For $(y,z)\in\mathcal S_{m'}$, the transverse
decay can be separated into attenuation
across the inter-waveguide gap and penetration
into the core of waveguide $m'$, giving
\begin{align}
&e^{-\alpha_y(y-y_m^{(\mathrm{WG})}-a/2)}
=\exp\left[
-\alpha_y\left(
\frac a2+y-y_{m'}^{(\mathrm{WG})}
\right)\right]
\nonumber
&\times
\exp\left[
-\alpha_y\left(
\left|y_m^{(\mathrm{WG})}
-y_{m'}^{(\mathrm{WG})}\right|-a
\right)\right].
\end{align}
Substituting the boundary field and the
above decay decomposition into
\eqref{eq:evanescent_from_boundary}
yields \eqref{eq:evanescent_field_mm}.
\end{proof}
\begin{proof}[Proof of Corollary~\ref{cor:optimal_waveguide_spacing}]
For $M=2$, $\operatorname{diag}(\bm C)=\bm 0$ and
$[\bm C]_{12}=[\bm C]_{21}=\mu(d)$.
Using the Taylor expansion of the matrix exponential, we obtain
\begin{align}
&e^{j\bm C(L_{n'}\!-\!L_n)} \nonumber 
&\!=\!
\begin{bmatrix}
\cos\!\big(\mu(d)(L_{n'}\!-\!L_n)\big)
&
j\sin\!\big(\mu(d)(L_{n'}\!-\!L_n)\big)
[0.2em]
j\sin\!\big(\mu(d)(L_{n'}\!-\!L_n)\big)
&
\cos\!\big(\mu(d)(L_{n'}\!-\!L_n)\big)
\end{bmatrix}.
\end{align}
Substituting the above into the dominant coherent term in
\eqref{eq:self_cross_coupling_gain} gives
\begin{align}
&2\Re\!\left\{
\bm h_{k,n}^{\mathsf H}
e^{j\bm C(L_{n'}-L_n)}
\bm h_{k,n'}
\right\}
\nonumber
=&\;
2\cos\!\big(\mu(d)(L_{n'}-L_n)\big)
\Re\!\left\{
\bm h_{k,n}^{\mathsf H}\bm h_{k,n'}
\right\}
\nonumber
&\;
-2\sin\!\big(\mu(d)(L_{n'}-L_n)\big)
\Im\!\left\{
\bm h_{k,n}^{\mathsf H}
\begin{bmatrix}
0&1
1&0
\end{bmatrix}
\bm h_{k,n'}
\right\}.
\end{align}
Next, using \eqref{eq:effective_channel_section}, and evaluating the
free-space propagation distances at a fixed reference geometry, the
phase difference between the section-$n$ and section-$n'$ responses is
approximated by the average propagation-phase difference across the
two waveguides, namely $\frac{1}{2}\sum_{m=1}^{2}
\Big(
k_0(r_{k,m_n}-r_{k,m_{n'}})
+
\beta_g(x_{m_n}^{(\mathrm{PA})}-x_{m_{n'}}^{(\mathrm{PA})})
\Big).$
Hence, the dominant coherent term can be approximated as
\begin{align*}
&2\Re\!\left\{
\bm h_{k,n}^{\mathsf H}
e^{j\bm C(L_{n'}-L_n)}
\bm h_{k,n'}
\right\}
\nonumber
\approx&
\;
2\|\bm h_{k,n}\|\,\|\bm h_{k,n'}\|
\cos\Bigg[
\mu(d)(L_{n'}-L_n)
\nonumber
&
-\frac{1}{2}\sum_{m=1}^{2}
\Big(
k_0(r_{k,m_n}-r_{k,m_{n'}})
+
\beta_g(x_{m_n}^{(\mathrm{PA})}-x_{m_{n'}}^{(\mathrm{PA})})
\Big)
\Bigg].
\end{align*}
Therefore, this coherent contribution is maximized when the cosine
term equals one, i.e.,
\begin{align}
\mu(d)(L_{n'}-L_n)
&=
\frac{1}{2}\sum_{m=1}^{2}
\Big[
k_0(r_{k,m_n}-r_{k,m_{n'}})\nonumber 
&+
\beta_g(x_{m_n}^{(\mathrm{PA})}-x_{m_{n'}}^{(\mathrm{PA})})
\Big]
+2\pi p,
\end{align}
where $p\in\mathbb Z$.
Finally, by using $\mu(d)=\mu(a)e^{-\alpha_y(d-a)},$
we obtain
\begin{align}
e^{-\alpha_y(d-a)}
=&\frac{1}{\mu(a)(L_{n'}-L_n)}
\Bigg[
\frac12\sum_{m=1}^{2}
\Big(
k_0(r_{k,m_n}-r_{k,m_{n'}})
\nonumber
&+\beta_g(x_{m_n}^{(\mathrm{PA})}
-x_{m_{n'}}^{(\mathrm{PA})})
\Big)+2\pi p
\Bigg].
\end{align}
Taking the natural logarithm on both sides and rearranging yields
\eqref{eq:closed_form_waveguide_spacing}.
\end{proof}
\begin{proof}[Proof of Lemma~\ref{lem:coupling_saturation}]
For the equally spaced deployment, the coupling
matrix satisfies $[\bm C]_{m,m}=0$ and
$[\bm C]_{m,m'}=\mu(d)e^{-\alpha_y(|m-m'|-1)d}$
for $m\neq m'$.
Since $\bm C$ is real symmetric and entrywise
nonnegative, its spectral norm satisfies
$\|\bm C\|_2=\lambda_{\max}(\bm C)$.
Evaluating the Rayleigh quotient at the
normalized all-ones vector
$\bm 1_M/\sqrt M$ gives
\begin{align}
\|\bm C\|_2
\ge&
\frac{2\mu(d)}{M}
\sum_{\ell=1}^{M-1}
(M-\ell)e^{-\alpha_y(\ell-1)d}
\nonumber
=&\frac{2\mu(d)}{1-e^{-\alpha_y d}}
\left[
1-\frac{1-e^{-\alpha_y Md}}
{M(1-e^{-\alpha_y d})}
\right],
\end{align}
where the last equality follows from
the finite geometric series.
For the upper bound, the symmetry of $\bm C$
implies $\|\bm C\|_2\leq\|\bm C\|_\infty$.
The absolute row sum of the $m$-th row is
\begin{align*}
&\sum_{m'=1}^{M}|[\bm C]_{m,m'}|
\!=\!\mu(d)\!\left[
\sum_{\ell=1}^{m-1}e^{-\alpha_y(\ell-1)d}
\!+\!\sum_{\ell=1}^{M-m}e^{-\alpha_y(\ell-1)d}
\right]
\nonumber
=&\frac{\mu(d)}{1-e^{-\alpha_y d}}
\left[
2-e^{-\alpha_y(m-1)d}
-e^{-\alpha_y(M-m)d}
\right].
\end{align*}
This row sum increases toward the center
of the matrix and decreases thereafter.
Hence, its maximum is attained at
$m=\lfloor(M+1)/2\rfloor$ or
$m=\lceil(M+1)/2\rceil$, yielding
\begin{align*}
\|\bm C\|_2
\leq&\|\bm C\|_\infty
\nonumber
=&\frac{\mu(d)}{1-e^{-\alpha_y d}}
\Bigg[
2-e^{-\alpha_y d\left\lfloor
\frac{M-1}{2}\right\rfloor}
-e^{-\alpha_y d\left\lceil
\frac{M-1}{2}\right\rceil}
\Bigg].
\end{align*}
Combining the two bounds completes the proof.
\end{proof}
\begin{proof}[Proof of Lemma~\ref{lem:rate_bound_scaling}]
With the transverse origin at the array center,
the equally spaced waveguides are located at
$y_m^{(\mathrm{WG})}=(m-(M+1)/2)d$.
For $\zeta=3$, the geometric sum in
\eqref{eq:rate_geometry_upper_bound}
can be approximated by midpoint integration:
\begin{align}
&\sum_{m=1}^{M}
\left[
1+\left(
\frac{y_m^{(\mathrm{WG})}-y^{(\mathrm{AE})}}
{D_z}
\right)^2
\right]^{-5/2}
\nonumber
\approx&
\frac{1}{d}
\int_{-Md/2}^{Md/2}
\left[
1+\left(
\frac{y-y^{(\mathrm{AE})}}{D_z}
\right)^2
\right]^{-5/2}
\mathrm dy.
\label{eq:rate_scaling_integral}
\end{align}
Using the integral identity
$\int(1+u^2)^{-5/2}\mathrm du
=\mathcal F(u)+\mathrm{const}$,
we obtain
\begin{align}
&\frac{1}{d}
\int_{-Md/2}^{Md/2}
\left[
1+\left(
\frac{y-y^{(\mathrm{AE})}}{D_z}
\right)^2
\right]^{-5/2}
\mathrm dy

=&\frac{D_z}{d}
\Bigg[
\mathcal F\left(
\frac{Md/2-y^{(\mathrm{AE})}}{D_z}
\right)
+
\mathcal F\left(
\frac{Md/2+y^{(\mathrm{AE})}}{D_z}
\right)
\Bigg].\nonumber
\end{align}
Substituting this result into
\eqref{eq:rate_geometry_upper_bound}
yields \eqref{eq:rate_bound_scaling_M}.
For $Md\ll D_z$, expanding the integrand
in \eqref{eq:rate_scaling_integral} around
the array center and retaining the
leading-order term gives
\begin{align*}
&\frac{1}{d}
\int_{-Md/2}^{Md/2}
\left[
1+\left(
\frac{y-y^{(\mathrm{AE})}}{D_z}
\right)^2
\right]^{-5/2}
\!\!\!\!\!\!\mathrm dy
\approx
\frac{M}{
\left[
1+\left(
\frac{y^{(\mathrm{AE})}}{D_z}
\right)^2
\right]^{5/2}
}.
\end{align*}
For $Md/2-|y^{(\mathrm{AE})}|\gg D_z$,
the agent is sufficiently far from both
array edges, allowing the integration limits
to be extended to infinity. Hence,
\begin{align}
&\frac{1}{d}
\int_{-Md/2}^{Md/2}
\left[
1+\left(
\frac{y-y^{(\mathrm{AE})}}{D_z}
\right)^2
\right]^{-5/2}
\mathrm dy
\nonumber
\approx&
\frac{D_z}{d}
\int_{-\infty}^{\infty}
(1+u^2)^{-5/2}\mathrm du
=\frac{4D_z}{3d}.
\end{align}
Substituting the two asymptotic expressions
into \eqref{eq:rate_geometry_upper_bound}
yields \eqref{eq:rate_bound_asymptotic}.
\end{proof}
\begin{proof}[Proof of Corollary~\ref{cor:waveguide_number_range}]
For each physical agent $k$, the minimum-rate
requirement $R_k\ge R_0$ implies
\begin{align}
P|\bm h_k^{\mathsf H}\bm w_k|^2
\ge&
(2^{R_0}-1)
\Bigg(
P\sum_{j\neq k}
|\bm h_k^{\mathsf H}\bm w_j|^2
+\sigma^2
\Bigg)
\nonumber
\ge&
(2^{R_0}-1)\sigma^2.
\end{align}
Applying the Cauchy--Schwarz inequality
$|\bm h_k^{\mathsf H}\bm w_k|^2
\le\|\bm h_k\|^2\|\bm w_k\|^2$
gives
\begin{equation}
P\|\bm h_k\|^2\|\bm w_k\|^2
\ge (2^{R_0}-1)\sigma^2.
\end{equation}
From \eqref{eq:rate_geometry_upper_bound},
each term in the transverse geometric sum
is at most one, so the sum is bounded by $M$.
Consequently, the channel gain satisfies
\begin{align*}
\|\bm h_k\|^2
\le&
\frac{
M\lambda^2(\zeta+1)
e^{-\alpha_{\mathrm W}\underline{x}_1}
}{
8\pi^2D_z^2
}
\left(
1+\frac{2}{N}
\sum_{n<n'}\cos\theta_{k,nn'}
\right).
\end{align*}
Combining the above inequalities with
the total precoding power constraint
$\sum_{k=1}^{K}\|\bm w_k\|^2\le 1$
yields
\begin{align}
1\ge&
\frac{
8\pi^2\sigma^2D_z^2
(2^{R_0}-1)
e^{\alpha_{\mathrm W}\underline{x}_1}
}{
PM\lambda^2(\zeta+1)
}
\nonumber
&\times
\sum_{k=1}^{K}
\left(
1+\frac{2}{N}
\sum_{n<n'}\cos\theta_{k,nn'}
\right)^{-1}.
\end{align}
Rearranging and noting that $M$ is an
integer gives the lower bound in (45).
Moreover, the $M$ equally spaced waveguides
must lie within the transverse deployment
interval of width $D_y$, requiring
$(M-1)d\le D_y$.
Since $M$ is an integer, this yields
$M\le 1+\lfloor D_y/d\rfloor$.
Combining the lower and upper bounds
completes the proof.
\end{proof}

